# The following helpers are assumed to be provided by the environment.
# node_by_title, node_by_id, children, scope_nodes, table_rows


def entities(doc: Dict, scope: str) -> List[Dict[str, str]]:
    """
    Return a list of distinct entity dictionaries {id, description}
    present in the given scope (e.g. 'Cell window 01').
    Entities are machines, tasks, and jobs.
    """
    res: List[Dict[str, str]] = []
    seen_ids = set()

    # Find the scope node
    scope_node = node_by_title(doc, scope)
    # All child tables
    for node in children(doc, scope_node):
        if node['kind'] != 'table':
            continue
        title = node['title']
        if 'Machines' in title:
            # Machine ids
            for _, row in table_rows(node):
                mid = row['machine']
                if mid not in seen_ids:
                    seen_ids.add(mid)
                    res.append({"id": mid, "description": f"machine {mid}"})
        elif 'Task log' in title:
            # Task and job ids
            for _, row in table_rows(node):
                tid = row['task']
                jid = row['job']
                if tid not in seen_ids:
                    seen_ids.add(tid)
                    res.append({"id": tid, "description": f"task {tid}"})
                if jid not in seen_ids:
                    seen_ids.add(jid)
                    res.append({"id": jid, "description": f"job {jid}"})
        elif 'Queue at window end' in title and 'Task running' in title:
            # Running tasks
            for _, row in table_rows(node):
                tid = row['task']
                jid = row['job']
                if tid not in seen_ids:
                    seen_ids.add(tid)
                    res.append({"id": tid, "description": f"task {tid}"})
                if jid not in seen_ids:
                    seen_ids.add(jid)
                    res.append({"id": jid, "description": f"job {jid}"})
        elif 'Queue at window end' in title and 'Tasks waiting' in title:
            # Waiting tasks
            for _, row in table_rows(node):
                tid = row['task']
                jid = row['job']
                if tid not in seen_ids:
                    seen_ids.add(tid)
                    res.append({"id": tid, "description": f"task {tid}"})
                if jid not in seen_ids:
                    seen_ids.add(jid)
                    res.append({"id": jid, "description": f"job {jid}"})
    return res


def recorded_end(doc: Dict, scope: str) -> Optional[float]:
    """
    Return the latest time point covered by the scope.
    We look in the Task log table 'time' column and in Events lines
    that mention 'Time <n>:'.
    """
    end_time = None
    scope_node = node_by_title(doc, scope)
    for node in children(doc, scope_node):
        if node['kind'] == 'table':
            for _, row in table_rows(node):
                # time column may exist
                if 'time' in row:
                    try:
                        t = int(row['time'])
                        if end_time is None or t > end_time:
                            end_time = t
                    except ValueError:
                        pass
        elif node['kind'] == 'list':
            for idx, line in enumerate(node['lines']):
                m = re.search(r'Time (\d+)', line)
                if m:
                    t = int(m.group(1))
                    if end_time is None or t > end_time:
                        end_time = t
    return float(end_time) if end_time is not None else None


