            if fields:
                outcome["fields"] = fields
                # Add involved machine to entities if present
                if "machine" in fields:
                    outcome["entities"].append(fields["machine"])
            res.append(outcome)

    # Snapshot: running tasks at the window end
    for child_id in children(doc, scope_node):
        node = node_by_id(doc, child_id)
        if node["kind"] != "table":
            continue
        title = node["title"]
        if "Tasks running" in title:
            for idx, row in table_rows(node):
                tid = row["task"]
                jid = row["job"]
                machine = row["machine"]
                started = int(row["started"])
                remaining = int(row["remaining"])
                res.append(
                    {
                        "time": None,
                        "kind": "queue_running_snapshot",
                        "entities": [tid, jid, machine],
                        "value": None,
                        "src": _loc_table(child_id, idx),
                        "fields": {"started_at": started, "remaining_run_time": remaining},
                    }
                )
        if "Tasks waiting" in title:
            for idx, row in table_rows(node):
                tid = row["task"]
                jid = row["job"]
                priority = int(row["priority"])
                cpu = int(row["CPU"])
                mem = int(row["memory"])
                submitted = int(row["submitted"])
                runtime = int(row["run time"])
                res.append(
                    {
                        "time": None,
                        "kind": "queue_waiting_snapshot",
                        "entities": [tid, jid],
                        "value": None,
                        "src": _loc_table(child_id, idx),
                        "fields": {
                            "priority": priority,
                            "cpu_req": cpu,
                            "mem_req": mem,
                            "submitted_at": submitted,
                            "run_time": runtime,
                        },
                    }
                )
    return res

def params(doc: Dict[str, Any], scope: str) -> Dict[str, Any]:
    """Document constants."""
    # Window length is fixed 1200 seconds, and we know the cluster always has 8 machines in this doc.
    return {"window_length": 1200, "num_machines": 8}
